SELECT txn_type, CASE WHEN amount >= 3300 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END AS amount_bucket, ROUND((100 * SUM(CASE WHEN txn_type = 'FEE' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_fee FROM transactions WHERE is_flagged GROUP BY txn_type, CASE WHEN amount >= 3300 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END HAVING ROUND((100 * SUM(CASE WHEN txn_type = 'FEE' THEN 1 ELSE 0 END)) / COUNT(*), 1) < 38 ORDER BY amount_bucket
